import { day44IdentityFixtureIds } from './seed-identity';

interface NodeHash {
  update(value: Uint8Array): NodeHash;
  digest(): Uint8Array;
}

declare const require: (moduleName: string) => unknown;

const { createHash } = require('node:crypto') as {
  createHash(algorithm: 'sha1'): NodeHash;
};
const { Buffer } = require('node:buffer') as {
  Buffer: { from(value: string, encoding: 'base64'): Uint8Array };
};

const ICT_OFFSET_MILLISECONDS = 7 * 60 * 60 * 1000;
const UUID_NAMESPACE = '44000000-0000-5000-8000-000000000001';
const LETTERS = ['A', 'B', 'C'] as const;
const ROUTES = ['r1', 'r2', 'r3'] as const;
const STATION_KEYS = ['mien-tay', 'mien-dong-moi', 'can-tho', 'long-chau', 'ben-tre'] as const;
const VEHICLE_TYPE_IDS = {
  STANDARD_BUS: '00000000-0000-0000-0000-000000000101',
  LIMOUSINE: '00000000-0000-0000-0000-000000000102',
  SLEEPER_BUS: '00000000-0000-0000-0000-000000000103',
} as const;

type OperatorLetter = (typeof LETTERS)[number];
type RouteKey = (typeof ROUTES)[number];
type FixtureRow = Readonly<Record<string, unknown>>;

export interface SeatLayoutSeat {
  seatNumber: string;
  row: number;
  col: number;
  deck: number;
  type: 'STANDARD' | 'VIP' | 'SLEEPER_LOWER' | 'SLEEPER_UPPER';
  isWindow: boolean;
  isAisle: boolean;
  disabled: false;
}

export interface SeatLayout {
  version: 1;
  vehicleTypeCode: 'STANDARD_BUS' | 'LIMOUSINE' | 'SLEEPER_BUS';
  totalSeats: number;
  rows: number;
  cols: number;
  decks: number;
  aisles: ReadonlyArray<{ afterCol: number }>;
  seats: ReadonlyArray<SeatLayoutSeat>;
}

export interface ExistingTripFixtureState {
  vehicleTypes: ReadonlyArray<FixtureRow>;
  stations: ReadonlyArray<FixtureRow>;
  operatorStations: ReadonlyArray<FixtureRow>;
  stops: ReadonlyArray<FixtureRow>;
  routes: ReadonlyArray<FixtureRow>;
  routeStops: ReadonlyArray<FixtureRow>;
  alternativeRoutes: ReadonlyArray<FixtureRow>;
  alternativeRouteStops: ReadonlyArray<FixtureRow>;
  vehicles: ReadonlyArray<FixtureRow>;
  driverSchedules: ReadonlyArray<FixtureRow>;
  trips: ReadonlyArray<FixtureRow>;
  tripSeats: ReadonlyArray<FixtureRow>;
  tripStops: ReadonlyArray<FixtureRow>;
  tripStopFares: ReadonlyArray<FixtureRow>;
}

export interface Day44TripPlannerInput {
  environment: string | undefined;
  startDate: string;
  currentInstant: Date;
  existingState: ExistingTripFixtureState;
  logger?: { info(message: string, fields: Readonly<Record<string, unknown>>): void };
}

export interface Day44TripFixturePlan extends ExistingTripFixtureState {
  schemaVersion: 1;
  namespace: 'day44-v1';
  timezone: 'Asia/Ho_Chi_Minh';
  startDate: string;
  tripDepartureInstantsByOperator: Readonly<Record<OperatorLetter, ReadonlyArray<string>>>;
  currentTripsThisMonthByOperator: Readonly<Record<OperatorLetter, number>>;
}

const LISTED_IDS_BASE64 =
  '';

function seatNumbers(route: RouteKey): ReadonlyArray<string> {
  if (route === 'r1')
    return Array.from({ length: 45 }, (_, index) => `S${String(index + 1).padStart(2, '0')}`);
  if (route === 'r2')
    return Array.from({ length: 9 }, (_, index) => `V${String(index + 1).padStart(2, '0')}`);
  return [
    ...Array.from({ length: 20 }, (_, index) => `L${String(index + 1).padStart(2, '0')}`),
    ...Array.from({ length: 20 }, (_, index) => `U${String(index + 1).padStart(2, '0')}`),
  ];
}

function listedFixtureKeys(): ReadonlyArray<string> {
  const keys: string[] = STATION_KEYS.map((key) => `trip:station:${key}`);
  LETTERS.forEach((letter) =>
    STATION_KEYS.forEach((key) =>
      keys.push(`trip:operator-station:${letter.toLowerCase()}:${key}`),
    ),
  );
  LETTERS.forEach((letter) =>
    [2, 3, 4].forEach((station) =>
      keys.push(`trip:stop:${letter.toLowerCase()}:station-copy:${station}`),
    ),
  );
  LETTERS.forEach((letter) =>
    ROUTES.forEach((route) => keys.push(`trip:route:${letter.toLowerCase()}:${route}`)),
  );
  LETTERS.forEach((letter) => keys.push(`trip:alternative-route:${letter.toLowerCase()}:r3:1`));
  LETTERS.forEach((letter) =>
    ROUTES.forEach((route) => keys.push(`trip:vehicle:${letter.toLowerCase()}:${route}`)),
  );
  LETTERS.forEach((letter) =>
    ROUTES.forEach((route) => keys.push(`trip:driver-schedule:${letter.toLowerCase()}:${route}`)),
  );
  LETTERS.forEach((letter) =>
    ROUTES.forEach((route) =>
      Array.from({ length: 14 }, (_, offset) => {
        const tripKey = `trip:trip:${letter.toLowerCase()}:${route}:d${String(offset).padStart(2, '0')}`;
        keys.push(tripKey);
        seatNumbers(route).forEach((seat) => keys.push(`${tripKey}:seat:${seat}`));
      }),
    ),
  );
  return keys;
}

function bytesToUuid(bytes: Uint8Array): string {
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function listedIds(): ReadonlyMap<string, string> {
  const keys = listedFixtureKeys();
  const bytes = Buffer.from(LISTED_IDS_BASE64, 'base64');
  if (bytes.length !== keys.length * 16) throw new Error('Day 44 Trip ID registry is incomplete');
  return new Map(
    keys.map((key, index) => [key, bytesToUuid(bytes.slice(index * 16, index * 16 + 16))]),
  );
}

const FIXTURE_IDS = listedIds();

function fixtureId(key: string): string {
  const value = FIXTURE_IDS.get(key);
  if (!value) throw new Error(`Day 44 Trip fixture ID is not listed for ${key}`);
  return value;
}

function uuidToBytes(uuid: string): Uint8Array {
  return Uint8Array.from(uuid.replaceAll('-', '').match(/.{2}/g) ?? [], (byte) =>
    Number.parseInt(byte, 16),
  );
}

function uuidV5(key: string): string {
  const namespace = uuidToBytes(UUID_NAMESPACE);
  const name = new TextEncoder().encode(key);
  const source = new Uint8Array(namespace.length + name.length);
  source.set(namespace);
  source.set(name, namespace.length);
  const bytes = createHash('sha1').update(source).digest().slice(0, 16);
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  return bytesToUuid(bytes);
}

function assertListedIds(): void {
  FIXTURE_IDS.forEach((id, key) => {
    if (uuidV5(key) !== id)
      throw new Error(`Day 44 manifest contains an invalid Trip fixture ID for ${key}`);
  });
}

function parseDate(value: string): { year: number; month: number; day: number } {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) throw new Error('startDate must use YYYY-MM-DD');
  const result = { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
  const check = new Date(Date.UTC(result.year, result.month - 1, result.day));
  if (
    check.getUTCFullYear() !== result.year ||
    check.getUTCMonth() + 1 !== result.month ||
    check.getUTCDate() !== result.day
  ) {
    throw new Error('startDate is not a valid ICT calendar date');
  }
  return result;
}

function ictInstant(date: string, hour = 0, minute = 0, offsetDays = 0): Date {
  const value = parseDate(date);
  return new Date(
    Date.UTC(value.year, value.month - 1, value.day + offsetDays, hour, minute) -
      ICT_OFFSET_MILLISECONDS,
  );
}

function dateOnly(date: string, offsetDays: number): string {
  const value = parseDate(date);
  return new Date(Date.UTC(value.year, value.month - 1, value.day + offsetDays))
    .toISOString()
    .slice(0, 10);
}

function ictParts(instant: Date): { year: number; month: number; day: number } {
  const shifted = new Date(instant.getTime() + ICT_OFFSET_MILLISECONDS);
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

function assertInputs(input: Day44TripPlannerInput): void {
  if (input.environment?.trim().toLowerCase() === 'production')
    throw new Error('Day 44 Trip fixture is forbidden in Production');
  if (Number.isNaN(input.currentInstant.getTime())) throw new Error('currentInstant is invalid');
  const start = parseDate(input.startDate);
  const current = ictParts(input.currentInstant);
  const startValue = start.year * 10_000 + start.month * 100 + start.day;
  const currentValue = current.year * 10_000 + current.month * 100 + current.day;
  if (startValue <= currentValue)
    throw new Error('startDate must be at least one day after the current ICT date');
}

