function auditFields(createdAt: string): { createdAt: string; updatedAt: string } {
  return { createdAt, updatedAt: createdAt };
}

function buildSeatLayout(route: RouteKey): SeatLayout {
  const configuration =
    route === 'r1'
      ? { code: 'STANDARD_BUS' as const, rows: 9, cols: 5, decks: 1, aisle: 3 }
      : route === 'r2'
        ? { code: 'LIMOUSINE' as const, rows: 3, cols: 3, decks: 1, aisle: 2 }
        : { code: 'SLEEPER_BUS' as const, rows: 5, cols: 4, decks: 2, aisle: 2 };
  const seats = seatNumbers(route).map((seatNumber, index): SeatLayoutSeat => {
    const deck = route === 'r3' && index >= 20 ? 2 : 1;
    const deckIndex = route === 'r3' ? index % 20 : index;
    const row = Math.floor(deckIndex / configuration.cols) + 1;
    const col = (deckIndex % configuration.cols) + 1;
    return {
      seatNumber,
      row,
      col,
      deck,
      type:
        route === 'r1'
          ? 'STANDARD'
          : route === 'r2'
            ? 'VIP'
            : deck === 1
              ? 'SLEEPER_LOWER'
              : 'SLEEPER_UPPER',
      isWindow: col === 1 || col === configuration.cols,
      isAisle: col === configuration.aisle || col === configuration.aisle + 1,
      disabled: false,
    };
  });
  return {
    version: 1,
    vehicleTypeCode: configuration.code,
    totalSeats: seats.length,
    rows: configuration.rows,
    cols: configuration.cols,
    decks: configuration.decks,
    aisles: [{ afterCol: configuration.aisle }],
    seats,
  };
}

function canonicalJson(value: unknown): string {
  const canonicalize = (current: unknown): unknown => {
    if (Array.isArray(current)) return current.map(canonicalize);
    if (current !== null && typeof current === 'object') {
      return Object.fromEntries(
        Object.entries(current)
          .sort(([left], [right]) => left.localeCompare(right))
          .map(([key, child]) => [key, canonicalize(child)]),
      );
    }
    return current;
  };
  return JSON.stringify(canonicalize(value));
}

function assertCollisionGate(
  label: string,
  existing: ReadonlyArray<FixtureRow>,
  expected: ReadonlyArray<FixtureRow>,
): void {
  const expectedStates = new Set(expected.map(canonicalJson));
  existing.forEach((row) => {
    if (!expectedStates.has(canonicalJson(row)))
      throw new Error(`Day 44 ${label} foreign natural-key collision or full-state mismatch`);
  });
}

export function planDay44TripFixture(input: Day44TripPlannerInput): Day44TripFixturePlan {
  assertInputs(input);
  assertListedIds();
  const createdAt = ictInstant(input.startDate, 0, 0, -2).toISOString();
  const audit = auditFields(createdAt);
  const vehicleTypes: FixtureRow[] = [
    {
      id: VEHICLE_TYPE_IDS.STANDARD_BUS,
      code: 'STANDARD_BUS',
      displayName: 'Xe ghế ngồi tiêu chuẩn',
      estimatedPassengerLuggageKgPerSeat: 10,
      defaultSeatCount: 45,
      isSystemDefined: true,
      isActive: true,
    },
    {
      id: VEHICLE_TYPE_IDS.LIMOUSINE,
      code: 'LIMOUSINE',
      displayName: 'Limousine',
      estimatedPassengerLuggageKgPerSeat: 15,
      defaultSeatCount: 9,
      isSystemDefined: true,
      isActive: true,
    },
    {
      id: VEHICLE_TYPE_IDS.SLEEPER_BUS,
      code: 'SLEEPER_BUS',
      displayName: 'Xe giường nằm',
      estimatedPassengerLuggageKgPerSeat: 20,
      defaultSeatCount: 40,
      isSystemDefined: true,
      isActive: true,
    },
  ];
  const stations: FixtureRow[] = stationDefinitions.map(
    ([key, name, slug, city, ward, latitude, longitude]) => ({
      id: fixtureId(`trip:station:${key}`),
      name,
      slug,
      addressStreet: null,
      city,
      ward,
      locationId: null,
      latitude,
      longitude,
      contactPhone: null,
      contactEmail: null,
      operatingHours: null,
      facilities: null,
      supportsShuttle: false,
      isActive: true,
      deletedAt: null,
      mergedIntoStationId: null,
      ...audit,
    }),
  );
  const operatorStations: FixtureRow[] = [];
  const stops: FixtureRow[] = [];
  const routes: FixtureRow[] = [];
  const routeStops: FixtureRow[] = [];
  const alternativeRoutes: FixtureRow[] = [];
  const alternativeRouteStops: FixtureRow[] = [];
  const vehicles: FixtureRow[] = [];
  const driverSchedules: FixtureRow[] = [];
  const trips: FixtureRow[] = [];
  const tripSeats: FixtureRow[] = [];
  const tripStops: FixtureRow[] = [];
  const tripDepartureInstantsByOperator = {
    A: [] as string[],
    B: [] as string[],
    C: [] as string[],
  };
  const layouts = {
    r1: buildSeatLayout('r1'),
    r2: buildSeatLayout('r2'),
    r3: buildSeatLayout('r3'),
  };

  LETTERS.forEach((letter, operatorIndex) => {
    const lower = letter.toLowerCase();
    const operatorId = day44IdentityFixtureIds.operators[letter];
    stations.forEach((station, stationIndex) =>
      operatorStations.push({
        id: fixtureId(`trip:operator-station:${lower}:${STATION_KEYS[stationIndex]}`),
        operatorId,
        stationId: station.id,
        displayNameOverride: null,
        counterLocation: null,
        contactPhone: null,
        instructions: null,
        isActive: true,
        ...audit,
      }),
    );
    [2, 3, 4].forEach((stationNumber) => {
      const station = stationDefinitions[stationNumber - 1];
      stops.push({
        id: fixtureId(`trip:stop:${lower}:station-copy:${stationNumber}`),
        operatorId,
        name: station[1],
        description: null,
        latitude: station[5],
        longitude: station[6],
        locationId: null,
        address: `${station[4]}, ${station[3]}`,
        googlePlaceId: null,
        sharedSuggestion: false,
        replacedByStopId: null,
        isActive: true,
        deletedAt: null,
        ...audit,
      });
    });

    const routeDefinitions = {
      r1: {
        name: `D44 ${letter} R1 Miền Tây - Cần Thơ`,
        origin: 0,
        destination: 2,
        fare: 180_000,
        distance: 170,
        duration: 240,
        time: '08:00:00',
        polyline: null,
      },
      r2: {
        name: `D44 ${letter} R2 Cần Thơ - Miền Tây`,
        origin: 2,
        destination: 0,
        fare: 180_000,
        distance: 170,
        duration: 240,
        time: '14:00:00',
        polyline: null,
      },
      r3: {
        name: `D44 ${letter} R3 Miền Tây - Bến Tre`,
        origin: 0,
        destination: 4,
        fare: 120_000,
        distance: 90,
        duration: 150,
        time: '10:00:00',
        polyline: 'ozp`As_wiSu`Zqoe@twiDf{jEmol@{ec@_sDcpmA',
      },
    } as const;
    ROUTES.forEach((route) => {
      const definition = routeDefinitions[route];
      routes.push({
        id: fixtureId(`trip:route:${lower}:${route}`),
        operatorId,
        name: definition.name,
        originStationId: stations[definition.origin].id,
        destinationStationId: stations[definition.destination].id,
        returnRouteId:
          route === 'r1'
            ? fixtureId(`trip:route:${lower}:r2`)
            : route === 'r2'
              ? fixtureId(`trip:route:${lower}:r1`)
              : null,
        baseFare: definition.fare,
        totalDistanceKm: definition.distance,
        estimatedDurationMinutes: definition.duration,
        pathPolyline: definition.polyline,
        isActive: true,
        deletedAt: null,
        ...audit,
      });
    });
    const operatorStops = stops.slice(operatorIndex * 3, operatorIndex * 3 + 3);
    const r3Id = fixtureId(`trip:route:${lower}:r3`);
    operatorStops.forEach((stop, index) =>
      routeStops.push({
        routeId: r3Id,
        stopId: stop.id,
        orderIndex: index + 1,
        estimatedDurationFromOriginMinutes: [35, 75, 115][index],
        distanceFromOriginKm: [30, 65, 80][index],
        allowPickup: true,
        allowDropoff: true,
        ...audit,
      }),
    );
    const alternativeRouteId = fixtureId(`trip:alternative-route:${lower}:r3:1`);
    alternativeRoutes.push({
      id: alternativeRouteId,
      routeId: r3Id,
      name: `D44 ${letter} R3 Alternative`,
      description: null,
      destinationStationId: stations[4].id,
      totalDistanceKm: 90,
      estimatedDurationMinutes: 150,
      pathPolyline: 'ozp`As_wiSpeaBxc`Cgg|BktfDtwiDf{jEmcr@_wqB',
      isActive: true,
      ...audit,
    });
    [2, 0, 1].forEach((stopIndex, index) =>
      alternativeRouteStops.push({
        alternativeRouteId,
        stopId: operatorStops[stopIndex].id,
        orderIndex: index + 1,
        estimatedDurationFromOriginMinutes: [35, 75, 115][index],
        distanceFromOriginKm: [30, 65, 80][index],
        ...audit,
      }),
    );

    ROUTES.forEach((route, routeIndex) => {
      const layout = layouts[route];
      const definition = routeDefinitions[route];
      const vehicleId = fixtureId(`trip:vehicle:${lower}:${route}`);
      const scheduleId = fixtureId(`trip:driver-schedule:${lower}:${route}`);
      const vehicleType =
        route === 'r1' ? 'STANDARD_BUS' : route === 'r2' ? 'LIMOUSINE' : 'SLEEPER_BUS';
      vehicles.push({
        id: vehicleId,
        operatorId,
        vehicleTypeId: VEHICLE_TYPE_IDS[vehicleType],
        licensePlate: `51B-${440 + operatorIndex}.${String(routeIndex + 1).padStart(2, '0')}`,
        seatLayoutJson: layout,
        totalSeats: layout.totalSeats,
        maxCargoWeightKg: 1000,
        maxCargoVolumeM3: 10,
        imageUrls: null,
        status: 'ACTIVE',
        isActive: true,
        deletedAt: null,
        ...audit,
      });
      driverSchedules.push({
        id: scheduleId,
        operatorId,
        routeId: fixtureId(`trip:route:${lower}:${route}`),
        vehicleId,
        driverUserId: day44IdentityFixtureIds.drivers[letter][routeIndex],
        assistantUserId: route === 'r1' ? day44IdentityFixtureIds.assistants[letter] : null,
        dayOfWeek: [1, 2, 3, 4, 5, 6, 7],
        departureTime: definition.time,
        validFrom: input.startDate,
        validUntil: dateOnly(input.startDate, 29),
        isActive: true,
        deletedAt: null,
        ...audit,
      });
      Array.from({ length: 14 }, (_, offset) => {
        const departure = ictInstant(
          input.startDate,
          Number(definition.time.slice(0, 2)),
          0,
          offset,
        );
        const departureIso = departure.toISOString();
        const tripId = fixtureId(`trip:trip:${lower}:${route}:d${String(offset).padStart(2, '0')}`);
        tripDepartureInstantsByOperator[letter].push(departureIso);
        trips.push({
          id: tripId,
          operatorId,
          routeId: fixtureId(`trip:route:${lower}:${route}`),
          alternativeRouteId: null,
          vehicleId,
          seatLayoutSnapshotJson: layout,
          driverUserId: day44IdentityFixtureIds.drivers[letter][routeIndex],
          assistantUserId: route === 'r1' ? day44IdentityFixtureIds.assistants[letter] : null,
          driverScheduleId: scheduleId,
          departureDateTime: departureIso,
          estimatedArrivalTime: new Date(
            departure.getTime() + definition.duration * 60_000,
          ).toISOString(),
          actualDepartureTime: null,
          destinationArrivedAt: null,
          destinationArrivedByUserId: null,
          completedAt: null,
          disruptedAt: null,
          disruptionReason: null,
          cancelledAt: null,
          cancelledByUserId: null,
          cancelReason: null,
          completedByUserId: null,
          notes: null,
          status: 'SCHEDULED',
          source: 'AUTO_FROM_SCHEDULE',
          hasSubstitution: false,
          baseFare: definition.fare,
          maxCargoWeightKg: 1000,
          maxCargoVolumeM3: 10,
          estimatedPassengerLuggageKg: route === 'r1' ? 450 : route === 'r2' ? 135 : 800,
          reservedParcelWeightKg: 0,
          reservedParcelVolumeM3: 0,
          totalLoadedWeightKg: 0,
          totalLoadedVolumeM3: 0,
          ...audit,
        });
        layout.seats.forEach((seat) =>
          tripSeats.push({
            id: fixtureId(
              `trip:trip:${lower}:${route}:d${String(offset).padStart(2, '0')}:seat:${seat.seatNumber}`,
            ),
            tripId,
            seatNumber: seat.seatNumber,
            seatType: seat.type,
            status: 'AVAILABLE',
            disabledReason: null,
            ...audit,
          }),
        );
        if (route === 'r3')
          operatorStops.forEach((stop, index) =>
            tripStops.push({
              tripId,
              stopId: stop.id,
              orderIndex: index + 1,
              estimatedArrivalTime: new Date(
                departure.getTime() + [35, 75, 115][index] * 60_000,
              ).toISOString(),
              actualArrivalTime: null,
              actualDepartureTime: null,
              status: 'PENDING',
              allowPickup: true,
              allowDropoff: true,
              distanceFromOriginKm: [30, 65, 80][index],
              ...audit,
            }),
          );
      });
    });
  });

  const currentTripsThisMonthByOperator = Object.fromEntries(
    LETTERS.map((letter) => {
      const start = parseDate(input.startDate);
      return [
        letter,
        tripDepartureInstantsByOperator[letter].filter((value) => {
          const parts = ictParts(new Date(value));
          return parts.year === start.year && parts.month === start.month;
        }).length,
      ];
    }),
  ) as Record<OperatorLetter, number>;
  const expected = {
    vehicleTypes,
    stations,
    operatorStations,
    stops,
    routes,
    routeStops,
    alternativeRoutes,
    alternativeRouteStops,
    vehicles,
    driverSchedules,
    trips,
    tripSeats,
    tripStops,
    tripStopFares: [] as FixtureRow[],
  };
  (Object.keys(expected) as Array<keyof typeof expected>).forEach((key) =>
    assertCollisionGate(key, input.existingState[key], expected[key]),
  );
  if (
    !vehicleTypes.every((type) =>
      input.existingState.vehicleTypes.some(
        (existing) => canonicalJson(existing) === canonicalJson(type),
      ),
    )
  ) {
    throw new Error('Day 44 requires the complete canonical VehicleType catalog');
  }
  input.logger?.info('Day 44 Trip fixture plan validated', {
    stations: stations.length,
    routes: routes.length,
    trips: trips.length,
    tripSeats: tripSeats.length,
    tripStops: tripStops.length,
  });
  return {
    schemaVersion: 1,
    namespace: 'day44-v1',
    timezone: 'Asia/Ho_Chi_Minh',
    startDate: input.startDate,
    ...expected,
    tripDepartureInstantsByOperator,
    currentTripsThisMonthByOperator,
  };
}
